EP = dict(id='WR25', tag='SYSTEMS', short='5 backups. 0 worked.', tail=1.0, bpm=116, drop_scenes=(4,),
          caption='GitLab had 5 backup systems. When they needed one, none worked. 💾\n\n31 Jan 2017: during a late-night database fix, an engineer deleted the data directory on the primary server instead of the secondary. ~300 GB gone. Their own postmortem: out of five backup/replication techniques, none were working reliably. A manual snapshot from 6 hours earlier saved them; 6 hours of data were lost. Lesson: test restores, not just backups.\n\nFull system design series on my page.\n💬 Comment NOTES for the cheat sheet.')
NARRATION = ['GitLab had five backup systems. When they needed one, none of them worked.', 'January 2017. Late at night, a tired engineer is fixing a database.', 'He runs a delete command. On the wrong server.', '300 gigabytes of live data. Gone in seconds.', 'Backup one: broken. Two: empty. Three, four, five: not working either.', 'One copy, made by hand six hours earlier, saved them. Six hours of data, lost.', 'A backup you never restore is not a backup.', 'Full system design series on my page. Follow.']
